import test from 'node:test';
import assert from 'node:assert/strict';
import { loadStandaloneTypeScript } from './patchproof_runtime/typescript_module.mjs';

const { formatBytes, formatSpeed } = loadStandaloneTypeScript('lib/utils/format.ts');

// Regression: formatBytes and formatSpeed render function source as literal text
// instead of resolved human-readable units.
test('formatBytes and formatSpeed return resolved units, not template literals', () => {
  // formatBytes 512 B
  assert.equal(formatBytes(512), '512 B';
  // formatBytes 1.0 KB (1024 bytes, one decimal place below 100)
  assert.equal(formatBytes(1024), '1.0 KB';
  // formatBytes 1.5 KB (1536 bytes)
  assert.equal(formatBytes(1536), '1.5 KB';
  // formatBytes 100 KB (102400 bytes)
  assert.equal(formatBytes(102400), '100 KB';
  // formatBytes 1.0 MB (1048576 bytes)
  assert.equal(formatBytes(1048576), '1.0 MB';
  // formatBytes 1.0 GB (1073741824 bytes)
  assert.equal(formatBytes(1073741824), '1.0 GB';
  // formatSpeed inherits formatBytes output
  assert.equal(formatSpeed(1536), '1.5 KB/s';
});

